def squash_plain_lines(grid, bg=0):
    """Every maximal run of plain lines (majority bg, between/around colored lines) collapses to one."""
    def colored(line):
        return sum(v != bg for v in line) > sum(v == bg for v in line)
    def filt(lines):
        out = []
        prev_plain = False
        for L in lines:
            pl = not colored(L)
            if pl and prev_plain:
                continue
            out.append(L)
            prev_plain = pl
        return out
    rows = filt([list(r) for r in grid])
    cols = filt([list(c) for c in zip(*rows)])
    return [list(r) for r in zip(*cols)]
'''
